#!/usr/bin/env bash
#
# The half of the attribution rule that the commit-message hook cannot see:
# a comment, docstring, file header or identifier naming an assistant, or
# announcing that a file was generated by one.
#
# Why it matters beyond taste: a file that announces itself as generated
# invites not reading it, and the tool's name never answers "why does this
# line exist".
#
# The matcher directory is excluded because a file listing forbidden strings
# necessarily contains them -- the same class as a `pgrep -f` pattern matching
# its own definition. Everything else comes from the project's own exclusion
# list, never from a path hard-coded here.
#
#   .claude/hooks/*     a pattern listing forbidden strings necessarily
#                       contains them. Same class as the `pgrep -f` trap
#                       already paid for here: a matcher finding its own
#                       definition. That directory holds only matchers.
#
. "$(dirname "$0")/lib-exclusions.sh"
EXCL=$(exclusions_regex)
set -euo pipefail

staged="$(git diff --cached --name-only --diff-filter=AM || true)"
[ -z "$staged" ] && exit 0

banned='Claude Code|Claude Opus|Claude Sonnet|Anthropic|ChatGPT|Copilot|generated by (an )?AI|AI-generated|written by Claude'

hits=""
while IFS= read -r f; do
  [ -n "$f" ] && [ -f "$f" ] || continue
  case "$f" in
    .claude/hooks/*) continue ;;   # a matcher necessarily contains its patterns
    *) printf '%s' "$f" | grep -qE "$EXCL" && continue ;;
  esac
  if grep -inE "$banned" "$f" >/dev/null 2>&1; then
    hits="$hits$(grep -inE "$banned" "$f" | sed "s|^|    $f:|")"$'\n'
  fi
done <<< "$staged"

if [ -n "$hits" ]; then
  echo "x Commit rejected: versioned content names an AI assistant." >&2
  printf '%s' "$hits" >&2
  exit 1
fi
